        root.Add(overlay);

        Label title = new Label("PAUSED");
        title.style.fontSize = 72;
        title.style.color = Color.white;
        title.style.marginBottom = 40;
        overlay.Add(title);

        overlay.Add(MakeButton("Resume", () => SetPaused(false)));
        overlay.Add(MakeButton("Restart Level", RestartLevel));
        overlay.Add(MakeButton("Quit to Menu", QuitToMenu));
    }

    private void OnDisable()
    {
        Time.timeScale = 1f;
        paused = false;
    }

    private void Update()
    {
