        Button button = new Button(onClick);
        button.text = text;
        button.style.width = 360;
        button.style.height = 64;
        button.style.fontSize = 28;
        button.style.marginBottom = 14;
        button.style.color = Color.white;
        button.style.backgroundColor = new Color(0.2f, 0.3f, 0.6f, 1f);
        return button;
