- Define a serializable LevelEntry (display name and scene name) and expose a list in the inspector.
- Read the unlocked level count from PlayerPrefs and build one button per level inside a ScrollView.
- Locked levels get a lock marker and are disabled; unlocked ones load their scene on click.

```csharp
using System;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.SceneManagement;
using UnityEngine.UIElements;

[Serializable]
public class LevelEntry
{
    public string displayName = "Level";
    public string sceneName = "Level1";
}

public class LevelSelectUI : MonoBehaviour
{
    public const string UnlockedKey = "UnlockedLevels";

    [SerializeField] private List<LevelEntry> levels = new List<LevelEntry>
    {
        new LevelEntry { displayName = "Level 1", sceneName = "Level1" },
        new LevelEntry { displayName = "Level 2", sceneName = "Level2" },
        new LevelEntry { displayName = "Level 3", sceneName = "Level3" },
    };

    private void OnEnable()
    {
        UIDocument doc = GetComponent<UIDocument>();
        if (doc == null) doc = gameObject.AddComponent<UIDocument>();
        if (doc.panelSettings == null)
        {
            PanelSettings settings = ScriptableObject.CreateInstance<PanelSettings>();
            settings.scaleMode = PanelScaleMode.ScaleWithScreenSize;
            settings.referenceResolution = new Vector2Int(1920, 1080);
            doc.panelSettings = settings;
        }

        VisualElement root = doc.rootVisualElement;
        root.Clear();
        root.style.flexGrow = 1;
        root.style.alignItems = Align.Center;
        root.style.paddingTop = 60;
        root.style.backgroundColor = new Color(0.07f, 0.09f, 0.13f, 1f);

        Label title = new Label("Select Level");
        title.style.fontSize = 60;
        title.style.color = Color.white;
        title.style.marginBottom = 30;
        root.Add(title);

        ScrollView list = new ScrollView();
        list.style.width = 520;
        list.style.flexGrow = 1;
        root.Add(list);

        int unlocked = Mathf.Max(1, PlayerPrefs.GetInt(UnlockedKey, 1));
        for (int i = 0; i < levels.Count; i++)
        {
            list.Add(BuildLevelButton(levels[i], i < unlocked));
        }
    }

    private Button BuildLevelButton(LevelEntry entry, bool isUnlocked)
    {
        string sceneName = entry.sceneName;
        Button button = new Button(() => SceneManager.LoadScene(sceneName));
        button.text = isUnlocked ? entry.displayName : entry.displayName + "   [LOCKED]";
        button.style.height = 70;
        button.style.fontSize = 30;
        button.style.marginBottom = 12;
        button.style.color = isUnlocked ? Color.white : new Color(0.6f, 0.6f, 0.6f, 1f);
        button.style.backgroundColor = isUnlocked
            ? new Color(0.2f, 0.45f, 0.8f, 1f)
            : new Color(0.2f, 0.2f, 0.25f, 1f);
        button.SetEnabled(isUnlocked);
        return button;
    }

    public static void UnlockUpTo(int levelCount)
    {
        int current = PlayerPrefs.GetInt(UnlockedKey, 1);
        if (levelCount > current)
        {
            PlayerPrefs.SetInt(UnlockedKey, levelCount);
            PlayerPrefs.Save();
        }
    }
}
```

The list of levels is edited in the inspector; the menu creates one button per entry and compares its index to the unlocked count stored in PlayerPrefs. Locked buttons are disabled, greyed and labelled. `LevelSelectUI.UnlockUpTo(n)` is a static helper a level-complete script can call to raise the unlocked count.

**Plan**
- Build a loading screen with a title, a progress bar and a percentage Label.
- Start SceneManager.LoadSceneAsync for the next scene with allowSceneActivation off, and map its 0-0.9 progress to 0-100%.
- Update the bar and label each frame, then activate the scene once the load reaches 100%.

```csharp
using System.Collections;
using UnityEngine;
using UnityEngine.SceneManagement;
using UnityEngine.UIElements;

public class LoadingScreenUI : MonoBehaviour
{
    [SerializeField] private string sceneToLoad = "";
    [SerializeField] private float minimumShowTime = 0.75f;

    private Label percentLabel;
    private VisualElement barFill;

    private void OnEnable()
    {
        UIDocument doc = GetComponent<UIDocument>();
        if (doc == null) doc = gameObject.AddComponent<UIDocument>();
        if (doc.panelSettings == null)
        {
            PanelSettings settings = ScriptableObject.CreateInstance<PanelSettings>();
            settings.scaleMode = PanelScaleMode.ScaleWithScreenSize;
            settings.referenceResolution = new Vector2Int(1920, 1080);
            doc.panelSettings = settings;
        }

        VisualElement root = doc.rootVisualElement;
        root.Clear();
        root.style.flexGrow = 1;
        root.style.alignItems = Align.Center;
        root.style.justifyContent = Justify.Center;
        root.style.backgroundColor = new Color(0.05f, 0.06f, 0.09f, 1f);

        Label title = new Label("Loading...");
        title.style.fontSize = 56;
        title.style.color = Color.white;
        title.style.marginBottom = 30;
        root.Add(title);

        VisualElement bar = new VisualElement();
        bar.style.width = 700;
        bar.style.height = 28;
        bar.style.backgroundColor = new Color(0.2f, 0.22f, 0.3f, 1f);
        bar.style.borderTopLeftRadius = 14;
        bar.style.borderTopRightRadius = 14;
        bar.style.borderBottomLeftRadius = 14;
        bar.style.borderBottomRightRadius = 14;
        root.Add(bar);

        barFill = new VisualElement();
        barFill.style.height = Length.Percent(100);
        barFill.style.width = Length.Percent(0);
        barFill.style.backgroundColor = new Color(0.3f, 0.8f, 0.45f, 1f);
        barFill.style.borderTopLeftRadius = 14;
        barFill.style.borderBottomLeftRadius = 14;
        bar.Add(barFill);

        percentLabel = new Label("0%");
        percentLabel.style.fontSize = 32;
        percentLabel.style.color = Color.white;
        percentLabel.style.marginTop = 16;
        root.Add(percentLabel);

        StartCoroutine(LoadRoutine());
    }

    private IEnumerator LoadRoutine()
    {
        AsyncOperation operation;
        if (string.IsNullOrEmpty(sceneToLoad))
        {
            int next = (SceneManager.GetActiveScene().buildIndex + 1) % SceneManager.sceneCountInBuildSettings;
            operation = SceneManager.LoadSceneAsync(next);
        }
        else
        {
            operation = SceneManager.LoadSceneAsync(sceneToLoad);
        }
        operation.allowSceneActivation = false;

        float shown = 0f;
        float elapsed = 0f;
        while (shown < 1f || elapsed < minimumShowTime)
        {
            elapsed += Time.unscaledDeltaTime;
            float target = Mathf.Clamp01(operation.progress / 0.9f);
            shown = Mathf.MoveTowards(shown, target, Time.unscaledDeltaTime * 1.5f);
            barFill.style.width = Length.Percent(shown * 100f);
            percentLabel.text = Mathf.RoundToInt(shown * 100f) + "%";
            yield return null;
        }

        operation.allowSceneActivation = true;
    }
}
```

Unity reports async progress only up to 0.9 while activation is held back, so the script divides by 0.9 to get a true 0–100% value. The displayed value moves smoothly toward that target and the loop waits for a minimum show time, so the bar never flickers. When it reaches 100% the scene is activated. Leave the scene name empty to load the next build index.

